/* Builds sgCharTemplateLevelIndex (int[64]): for each CharTemplate level the index of its first
   row. Rows (stride 0xf0, level byte at +0x1f) must be sorted by ascending level; halts at line
   0x5c otherwise. */

void D2Common::DATATBLS::ArenaTbls::TXT_BuildCharTemplateLevelIndex
               (D2CharTemplateTxt *pCharTemplateTxt,int32_t nCount)

{
  int nLevel;
  void *nErrorAddr;
  int i;
  int nPrevLevel;
  uint8_t *pLevelField;
  int32_t nLine;

  compiler::memset(sgCharTemplateLevelIndex,0,0x100);
  nPrevLevel = 0;
  i = 0;
  if (0 < nCount) {
    pLevelField = &pCharTemplateTxt->level;
    do {
      nLevel = (int)*pLevelField;
      if ((uint)nLevel < (uint)nPrevLevel) {
        nLine = 0x5c;
        nErrorAddr = Fog::Src::ErrorManager::GetInstructionPointer();
        Fog::Src::ErrorManager::ERROR_UnrecoverableInternalError_Halt("",nErrorAddr,nLine);
                    /* WARNING: Subroutine does not return */
        compiler::exit(-1);
      }
      if ((uint)nPrevLevel < (uint)nLevel) {
        sgCharTemplateLevelIndex[nLevel] = i;
        nPrevLevel = nLevel;
      }
      i = i + 1;
      pLevelField = pLevelField + 0xf0;
    } while (i < nCount);
  }
  return;
}

